(3660967, 511368, 3087, '<td valign="top">Beautiful flowers, simply presented, nice composition with the sweeping curves. Lighting possibly a little flat.</td>', 'Beautiful flowers, simply presented, nice composition with the sweeping curves. Lighting possibly a little flat.', '2007-05-17 18:35:58.000000', NULL, 1),
(3660968, 510544, 3087, '<td valign="top">Yeah, now that''s nice framing.</td>', 'Yeah, now that''s nice framing.', '2007-05-17 18:36:14.000000', NULL, 1),
(3660973, 511055, 3087, '<td valign="top">Great photo! A real action shot. Lovely colours and detail.</td>', 'Great photo! A real action shot. Lovely colours and detail.', '2007-05-17 18:37:31.000000', NULL, 1),
(3660977, 510166, 3087, '<td valign="top">Nice photo - love the unusual viewpoint, the shallow DOF and the way it''s floating within the frame.</td>', 'Nice photo - love the unusual viewpoint, the shallow DOF and the way it''s floating within the frame.', '2007-05-17 18:38:31.000000', NULL, 1),
(3660978, 510678, 3087, '<td valign="top">Ha haaa, ha ha haa! Wicked! Love that" That''s just too funny. And those colours - the green, purple and turquoise - they are just too funky!</td>', 'Ha haaa, ha ha haa! Wicked! Love that" That''s just too funny. And those colours - the green, purple and turquoise - they are just too funky!', '2007-05-17 18:39:08.000000', NULL, 1),
(3660981, 511018, 3087, '<td valign="top">Wow, I love this shot. The high contrast, the incredible detail, that texture of the dessicated leaf and then the surface beneath, the wonderful shapes of the light and shadows, the composition with the leaf and darkness of the background below and the lighter lines of the surface leading away upwards... oh yes. And I like the text position and font too. Yup.</td>', 'Wow, I love this shot. The high contrast, the incredible detail, that texture of the dessicated leaf and then the surface beneath, the wonderful shapes of the light and shadows, the composition with the leaf and darkness of the background below and the lighter lines of the surface leading away upwards... oh yes. And I like the text position and font too. Yup.', '2007-05-17 18:40:54.000000', NULL, 1),
(3660987, 511269, 41337, '<td valign="top">This works for me as an album cover so good job there. If you care at all about your score and how to make it better I would have tried to get more wow factor into the shot somehow. The photo itself doesn''t have any so at least make the text more interesting such as having the part that says "Blinkenlights" look more like the lights in the background. Just a thought.</td>', 'This works for me as an album cover so good job there. If you care at all about your score and how to make it better I would have tried to get more wow factor into the shot somehow. The photo itself doesn''t have any so at least make the text more interesting such as having the part that says "Blinkenlights" look more like the lights in the background. Just a thought.', '2007-05-17 18:42:45.000000', NULL, 1),
(3660993, 510791, 3087, '<td valign="top">"According to its proponents, Dada was not art  it was "anti-art". For everything that art stood for, Dada was to represent the opposite. Where art was concerned with aesthetics, Dada ignored aesthetics. If art were to have at least an implicit or latent message, Dada strove to have no meaning  interpretation of Dada is dependent entirely on the viewer. If art is to appeal to sensibilities, Dada is to offend."<br/> <br/>Yeah, you nailed it. :o)</td>', '"According to its proponents, Dada was not art  it was "anti-art". For everything that art stood for, Dada was to represent the opposite. Where art was concerned with aesthetics, Dada ignored aesthetics. If art were to have at least an implicit or latent message, Dada strove to have no meaning  interpretation of Dada is dependent entirely on the viewer. If art is to appeal to sensibilities, Dada is to offend." Yeah, you nailed it. :o)', '2007-05-17 18:44:10.000000', NULL, 1),
(3661001, 511262, 3087, '<td valign="top">Haha, interesting picture. What an odd juxtaposition of those soft, warm bodies and that harsh, hard concrete! The selective desat works well too.</td>', 'Haha, interesting picture. What an odd juxtaposition of those soft, warm bodies and that harsh, hard concrete! The selective desat works well too.', '2007-05-17 18:45:33.000000', NULL, 1),
(3661004, 509425, 3087, '<td valign="top">I like the image a lot. The backlighting is beautiful in the way it creates halos of the small child''s hair and that line of gold around the other. I like the framing provided by the two hanging rings top left and right.</td>', 'I like the image a lot. The backlighting is beautiful in the way it creates halos of the small child''s hair and that line of gold around the other. I like the framing provided by the two hanging rings top left and right.', '2007-05-17 18:46:43.000000', NULL, 1),
(3661009, 511014, 3087, '<td valign="top">Like the image, like the composition, like the processing treatment and noise/ grain and the album title too.</td>', 'Like the image, like the composition, like the processing treatment and noise/ grain and the album title too.', '2007-05-17 18:48:00.000000', NULL, 1),
(3661011, 510806, 3087, '<td valign="top">Wow, very cool image. Really unusual. Works.</td>', 'Wow, very cool image. Really unusual. Works.', '2007-05-17 18:48:04.000000', NULL, 1),
(3661039, 511309, 76185, '<td valign="top">Fun idea and nice set up with the cans although feels a bit cluttered with the fridge full of random stuff.</td>', 'Fun idea and nice set up with the cans although feels a bit cluttered with the fridge full of random stuff.', '2007-05-17 18:58:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3661045, 509425, 76185, '<td valign="top">Nice shot, fits the title well although level is slightly distracting.</td>', 'Nice shot, fits the title well although level is slightly distracting.', '2007-05-17 18:59:56.000000', NULL, 1),
(3661054, 510714, 76185, '<td valign="top">Thats just scary... Good idea well executed though.</td>', 'Thats just scary... Good idea well executed though.', '2007-05-17 19:01:20.000000', NULL, 1),
(3661171, 511439, 76185, '<td valign="top">Fun title, shot set up is interesting but the lighting lets it down a little.</td>', 'Fun title, shot set up is interesting but the lighting lets it down a little.', '2007-05-17 19:39:43.000000', NULL, 1),
(3661181, 510950, 76185, '<td valign="top">Has a great album feel to the shot with crisp detail on the subject. Composition feel slightly off but not too distracting.</td>', 'Has a great album feel to the shot with crisp detail on the subject. Composition feel slightly off but not too distracting.', '2007-05-17 19:42:50.000000', NULL, 1),
(3661187, 510995, 76185, '<td valign="top">Simple and effective, although image could be clearer - looks like water on the windscreen.</td>', 'Simple and effective, although image could be clearer - looks like water on the windscreen.', '2007-05-17 19:44:14.000000', NULL, 1),
(3661221, 511298, 76185, '<td valign="top">Interesting choice of effect. Doesn''t quite work for me but it is well done.</td>', 'Interesting choice of effect. Doesn''t quite work for me but it is well done.', '2007-05-17 19:59:38.000000', NULL, 1),
(3661230, 510837, 76185, '<td valign="top">Great shot, feels like a real album cover type picture. Have to say the lettering lets it down a little imo :/</td>', 'Great shot, feels like a real album cover type picture. Have to say the lettering lets it down a little imo :/', '2007-05-17 20:01:32.000000', NULL, 1),
(3661238, 510791, 50695, '<td valign="top">Those panty liners look like they''re being toasted! I love the grill marks!<br/> <br/>This is 100% pure Dada, no additives or fillings. I bet the band actually uses those blinds as an instrument, sweeping them with a toothbrush for percussion.<br/> <br/>10, of course.</td>', 'Those panty liners look like they''re being toasted! I love the grill marks! This is 100% pure Dada, no additives or fillings. I bet the band actually uses those blinds as an instrument, sweeping them with a toothbrush for percussion. 10, of course.', '2007-05-17 20:04:36.000000', NULL, 1),
(3661241, 511047, 76185, '<td valign="top">A bit shoehorned but pretty nonetheless.</td>', 'A bit shoehorned but pretty nonetheless.', '2007-05-17 20:05:29.000000', NULL, 1),
(3661245, 511451, 76185, '<td valign="top">love the shot, nice different title</td>', 'love the shot, nice different title', '2007-05-17 20:07:01.000000', NULL, 1),
(3661260, 511262, 76446, '<td valign="top">nice</td>', 'nice', '2007-05-17 20:10:28.000000', NULL, 1),
(3661356, 510806, 50695, '<td valign="top">An Irish band who are brilliant but take three years to make an album because they get too drunk to record. Except for that guy in the polo shirt. It''s his job to be sober and worry about everyone else. They make fun of him, but they love him.<br/> <br/>10</td>', 'An Irish band who are brilliant but take three years to make an album because they get too drunk to record. Except for that guy in the polo shirt. It''s his job to be sober and worry about everyone else. They make fun of him, but they love him. 10', '2007-05-17 20:31:32.000000', NULL, 1),
(3661393, 510995, 50695, '<td valign="top">This is DPL''s first and what many consider to be their best album. They would always name their albums with a phrase that seemed to naturally follow "Don''t Panic, Love..." such as "Light Has Entered You" and "Time Never Waited", but soon their titles seemed more and more ironic. "The Wheat is in the Thresher" was followed by "I Already Left," which not so coincidentally was released after the band had broken up, at which point they slowly faded from memory, with the exception of a couple of road movies co-starring the lead guitarist and the drummer, "Panic Attack at 70MPH" and "Panic Attack 2: Pile Up!" The failure of these movies was largely due to creative differences between the musicians cum actors and the director, known primarily for his action movies. It seems the actors wanted the movies to be sullen, calypso dreams, in the mood of their first album cover.<br/> <br/>10</td>', 'This is DPL''s first and what many consider to be their best album. They would always name their albums with a phrase that seemed to naturally follow "Don''t Panic, Love..." such as "Light Has Entered You" and "Time Never Waited", but soon their titles seemed more and more ironic. "The Wheat is in the Thresher" was followed by "I Already Left," which not so coincidentally was released after the band had broken up, at which point they slowly faded from memory, with the exception of a couple of road movies co-starring the lead guitarist and the drummer, "Panic Attack at 70MPH" and "Panic Attack 2: Pile Up!" The failure of these movies was largely due to creative differences between the musicians cum actors and the director, known primarily for his action movies. It seems the actors wanted the movies to be sullen, calypso dreams, in the mood of their first album cover. 10', '2007-05-17 20:40:36.000000', NULL, 1),
(3661397, 511278, 50695, '<td valign="top">A great band but of course they only made one album. Half of their members died on their first cross-country tour.<br/> <br/>10</td>', 'A great band but of course they only made one album. Half of their members died on their first cross-country tour. 10', '2007-05-17 20:41:37.000000', NULL, 1),
(3661407, 511262, 50695, '<td valign="top">The name of this band was no marketing gimmick. Tad and Lu were exhibitionists to the core. Their fondness for onstage shenanigans ended tragically, though, when they short-circuited an electric guitar.<br/> <br/>10</td>', 'The name of this band was no marketing gimmick. Tad and Lu were exhibitionists to the core. Their fondness for onstage shenanigans ended tragically, though, when they short-circuited an electric guitar. 10', '2007-05-17 20:44:07.000000', NULL, 1),
(3661425, 510786, 50695, '<td valign="top">More of a "project" than a "band," designing perfect lives is the brainchild of Jimsus Calibray, one of the new breed of laptop musicians. Named after his mother''s two biggest heroes, Jimmie Dean and Jesus, Jimsus was obsessed with Kurt Vonnegut novels. Finally, he decided to write the soundtrack to Cat''s Cradle. When he ran into copyright troubles, he decided to write his own Kurt Vonnegut novel about a society controlled by pills. <br/> <br/>Finding the writing of novels a tremendously tedious task, he ended up skipping that step and going directly to the soundtrack, which also became the name of his "band"<br/> <br/>The rest is Scifitronica history.<br/> <br/>10</td>', 'More of a "project" than a "band," designing perfect lives is the brainchild of Jimsus Calibray, one of the new breed of laptop musicians. Named after his mother''s two biggest heroes, Jimmie Dean and Jesus, Jimsus was obsessed with Kurt Vonnegut novels. Finally, he decided to write the soundtrack to Cat''s Cradle. When he ran into copyright troubles, he decided to write his own Kurt Vonnegut novel about a society controlled by pills.  Finding the writing of novels a tremendously tedious task, he ended up skipping that step and going directly to the soundtrack, which also became the name of his "band" The rest is Scifitronica history. 10', '2007-05-17 20:48:56.000000', NULL, 1),
(3661428, 510092, 42013, '<td valign="top">Robert? Fantastic shot and someone obviously knows there way around lighting a bloom.</td>', 'Robert? Fantastic shot and someone obviously knows there way around lighting a bloom.', '2007-05-17 20:49:29.000000', NULL, 1),
(3661503, 510870, 73412, '<td valign="top">She looks like elaine from seinfeld</td>', 'She looks like elaine from seinfeld', '2007-05-17 21:11:41.000000', NULL, 1),
(3661770, 510776, 50695, '<td valign="top">SHAVE ME<br/> <br/>My legs are blue<br/>What can I do<br/>but dream of you<br/> <br/>as you shave me<br/> <br/>hold them aloft<br/>they''ll be so soft<br/>when the hair comes off<br/> <br/>as you shave me<br/> <br/>electric disposable silvery blades<br/>descending to sing me a sharp serenade<br/> <br/>shave me shave me shave me<br/> <br/>waving like a see of hair<br/>over here and under there<br/> <br/>shave me shave me shave me<br/> <br/>10</td>', 'SHAVE ME My legs are blueWhat can I dobut dream of you as you shave me hold them aloftthey''ll be so softwhen the hair comes off as you shave me electric disposable silvery bladesdescending to sing me a sharp serenade shave me shave me shave me waving like a see of hairover here and under there shave me shave me shave me 10', '2007-05-17 22:47:18.000000', NULL, 1),
(3661779, 511442, 50695, '<td valign="top">The devoted pasta lovers were known as the best (only?) Italian house music band of the 90''s. Interestingly enough, they really couldn''t dance. In fact, it was when they were spotted in the Limelight trying to dance that their songs stopped selling.<br/> <br/>10</td>', 'The devoted pasta lovers were known as the best (only?) Italian house music band of the 90''s. Interestingly enough, they really couldn''t dance. In fact, it was when they were spotted in the Limelight trying to dance that their songs stopped selling. 10', '2007-05-17 22:52:39.000000', NULL, 1),
(3661787, 511338, 50695, '<td valign="top">DPL named themselves after a psychological self-help book designed to help codependent people ease out of hurtful relationships. They were very successful until the bass player actually read the book and realized what complete jerks his bandmates were. 8</td>', 'DPL named themselves after a psychological self-help book designed to help codependent people ease out of hurtful relationships. They were very successful until the bass player actually read the book and realized what complete jerks his bandmates were. 8', '2007-05-17 22:55:15.000000', NULL, 1),
(3661792, 510920, 50695, '<td valign="top">DPL got its name from the lead singer''s wife. They used to be called Macho Macho Men but were threatened by a law suit from the Village People (that was the only thing the Village People did that year. It was right before their ill-fated New Year''s Eve with Dick Clark comeback). 7</td>', 'DPL got its name from the lead singer''s wife. They used to be called Macho Macho Men but were threatened by a law suit from the Village People (that was the only thing the Village People did that year. It was right before their ill-fated New Year''s Eve with Dick Clark comeback). 7', '2007-05-17 22:57:22.000000', NULL, 1),
(3661797, 510838, 50695, '<td valign="top">dpL started in an ashram in Kentucky, when three hillbilly monks realized that their chants were harmonizing really well, and smelled much dinero. Unfortunately, the success of their first album ruined their inner peace and they became Episcopalians, at which point they were no longer able to stay in tune. 9 (10 if it were square)</td>', 'dpL started in an ashram in Kentucky, when three hillbilly monks realized that their chants were harmonizing really well, and smelled much dinero. Unfortunately, the success of their first album ruined their inner peace and they became Episcopalians, at which point they were no longer able to stay in tune. 9 (10 if it were square)', '2007-05-17 23:00:21.000000', NULL, 1),
(3661811, 511398, 50695, '<td valign="top">It''s a little known fact that Stevie Wonder plays keyboards for this band, whose frontman, Karpov Key, amazingly was indeed deaf. And the drummer never spoke. They are more commonly known by the name they switched to for their re-ponymous third album: "The Three Monkeys"<br/> <br/>8</td>', 'It''s a little known fact that Stevie Wonder plays keyboards for this band, whose frontman, Karpov Key, amazingly was indeed deaf. And the drummer never spoke. They are more commonly known by the name they switched to for their re-ponymous third album: "The Three Monkeys" 8', '2007-05-17 23:04:39.000000', NULL, 1),
(3661833, 511127, 50695, '<td valign="top">This was DPL''s best album, but it''s disappointing sales ended up tearing apart the band. Fans were confused by the lack of lyrics and how the songs didn''t have beginnings or endings, they just tangled together. The fault lay squarely with their percussionist Tito, who wrote all the "songs" on this album during a dream, or so he claimed. He dreamed that he was writing music by sticking apple seeds into a pear... and amazingly was able to remember and transcribe every note when he woke up. Forcing his bandmates to be true to his dream, he created a work of true vision and integrity, a work doomed to fail in this sad, waking world.<br/> <br/>10</td>', 'This was DPL''s best album, but it''s disappointing sales ended up tearing apart the band. Fans were confused by the lack of lyrics and how the songs didn''t have beginnings or endings, they just tangled together. The fault lay squarely with their percussionist Tito, who wrote all the "songs" on this album during a dream, or so he claimed. He dreamed that he was writing music by sticking apple seeds into a pear... and amazingly was able to remember and transcribe every note when he woke up. Forcing his bandmates to be true to his dream, he created a work of true vision and integrity, a work doomed to fail in this sad, waking world. 10', '2007-05-17 23:10:15.000000', NULL, 1),
(3661901, 510995, 61651, '<td valign="top">Love the band name and intertwining title, and the image is, well I don''t know what it "is", I just like it very much. :)  This could pass for a real album cover. 10</td>', 'Love the band name and intertwining title, and the image is, well I don''t know what it "is", I just like it very much. :)  This could pass for a real album cover. 10', '2007-05-17 23:42:25.000000', NULL, 1),
